CREATE TABLE "public"."comment_target" (
  "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "artist_id" INTEGER REFERENCES "public"."artist" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "release_id" INTEGER REFERENCES "public"."release" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "song_id" INTEGER REFERENCES "public"."song" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "label_id" INTEGER REFERENCES "public"."label" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "event_id" INTEGER REFERENCES "public"."event" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "tag_id" INTEGER REFERENCES "public"."tag" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  "correction_id" INTEGER REFERENCES "public"."correction" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  PRIMARY KEY ("id"),
  CONSTRAINT "uniq_comment_target_artist_id" UNIQUE ("artist_id"),
  CONSTRAINT "uniq_comment_target_release_id" UNIQUE ("release_id"),
  CONSTRAINT "uniq_comment_target_song_id" UNIQUE ("song_id"),
  CONSTRAINT "uniq_comment_target_label_id" UNIQUE ("label_id"),
  CONSTRAINT "uniq_comment_target_event_id" UNIQUE ("event_id"),
  CONSTRAINT "uniq_comment_target_tag_id" UNIQUE ("tag_id"),
  CONSTRAINT "uniq_comment_target_correction_id" UNIQUE ("correction_id"),
  CONSTRAINT "ck_comment_target_exactly_one_target" CHECK (
    num_nonnulls(
      "artist_id",
      "release_id",
      "song_id",
      "label_id",
      "event_id",
      "tag_id",
      "correction_id"
    ) = 1
  )
);

CREATE TABLE "public"."comment_thread" (
  "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "target_id" INTEGER NOT NULL REFERENCES "public"."comment_target" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  PRIMARY KEY ("id"),
  CONSTRAINT "uniq_comment_thread_target_id" UNIQUE ("target_id")
);

ALTER TABLE "public"."comment"
  ADD COLUMN "thread_id" INTEGER;

INSERT INTO "public"."comment_target" ("artist_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Artist'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("release_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Release'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("song_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Song'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("label_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Label'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("event_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Event'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("tag_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Tag'
GROUP BY "target_id";

INSERT INTO "public"."comment_target" ("correction_id")
SELECT "target_id"
FROM "public"."comment"
WHERE "target"::text = 'Correction'
GROUP BY "target_id";

INSERT INTO "public"."comment_thread" ("target_id")
SELECT "target_ref"."id"
FROM
  "public"."comment" AS "comment"
  JOIN "public"."comment_target" AS "target_ref" ON (
    (
      "comment"."target"::text = 'Artist'
      AND "target_ref"."artist_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Release'
      AND "target_ref"."release_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Song'
      AND "target_ref"."song_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Label'
      AND "target_ref"."label_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Event'
      AND "target_ref"."event_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Tag'
      AND "target_ref"."tag_id" = "comment"."target_id"
    )
    OR (
      "comment"."target"::text = 'Correction'
      AND "target_ref"."correction_id" = "comment"."target_id"
    )
  )
GROUP BY "target_ref"."id"
ON CONFLICT ("target_id") DO NOTHING
;

UPDATE "public"."comment" AS "comment" SET
  "thread_id" = "thread"."id"
FROM
  "public"."comment_thread" AS "thread"
  JOIN "public"."comment_target" AS "target_ref" ON "thread"."target_id" = "target_ref"."id"
WHERE
  (
    "comment"."target"::text = 'Artist'
    AND "target_ref"."artist_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Release'
    AND "target_ref"."release_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Song'
    AND "target_ref"."song_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Label'
    AND "target_ref"."label_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Event'
    AND "target_ref"."event_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Tag'
    AND "target_ref"."tag_id" = "comment"."target_id"
  )
  OR (
    "comment"."target"::text = 'Correction'
    AND "target_ref"."correction_id" = "comment"."target_id"
  );

ALTER TABLE "public"."comment"
  ALTER COLUMN "thread_id"
SET NOT NULL;

ALTER TABLE
  "public"."comment"
  DROP CONSTRAINT IF EXISTS "fk_comment_parent_id_target_target_id",
  DROP CONSTRAINT IF EXISTS "comment_parent_id_fkey",
  DROP CONSTRAINT IF EXISTS "uniq_comment_id_target_target_id",
  DROP CONSTRAINT IF EXISTS "fk_comment_target_id_correction_id";

DROP INDEX IF EXISTS "public"."idx_comment_correction_list";

ALTER TABLE
  "public"."comment"
  ADD CONSTRAINT "fk_comment_thread_id" FOREIGN KEY ("thread_id") REFERENCES "public"."comment_thread" ("id") ON UPDATE CASCADE ON DELETE CASCADE,
  ADD CONSTRAINT "uniq_comment_id_thread_id" UNIQUE ("id", "thread_id"),
  ADD CONSTRAINT "fk_comment_parent_id_thread_id" FOREIGN KEY ("parent_id", "thread_id") REFERENCES "public"."comment" ("id", "thread_id") ON UPDATE CASCADE ON DELETE CASCADE;

CREATE INDEX "idx_comment_thread_list" ON "public"."comment" ("thread_id", "created_at", "id");

ALTER TABLE "public"."comment"
  DROP COLUMN "target",
    DROP COLUMN "target_id";
